?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>AI Visibility · TechSelectAI</title><style>body{font-family:Inter,system-ui,sans-serif;background:#f6f8fb;color:#172033;margin:0}main{max-width:1240px;margin:auto;padding:28px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.card,.panel{background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:16px}.panel{margin-top:18px}.filters,.actions{display:flex;gap:10px;flex-wrap:wrap;align-items:center}select,input,textarea,button{padding:9px;border:1px solid #cbd5e1;border-radius:8px;background:#fff}button{background:#173b63;color:#fff;border:0;cursor:pointer}textarea{width:100%;min-height:210px;box-sizing:border-box;font-family:ui-monospace,monospace}table{width:100%;border-collapse:collapse}th,td{padding:9px;border-bottom:1px solid #eef2f7;text-align:left;vertical-align:top}.muted{color:#64748b;font-size:12px}.n{font-size:28px;font-weight:800}.good{color:#166534}.bad{color:#b91c1c}@media(max-width:800px){.grid{grid-template-columns:1fr 1fr}table{display:block;overflow:auto}}@media(max-width:500px){.grid{grid-template-columns:1fr}}</style></head><body><main><h1>AI Visibility Benchmark</h1><p class="muted">Measure whether TechSelectAI is mentioned or cited across major AI/search assistants. Failed or ambiguous observations are stored but excluded from rates.</p><div class="filters"><select id="provider"><option value="">All providers</option><option>ChatGPT</option><option>Gemini</option><option>Claude</option><option>Perplexity</option></select><select id="days"><option value="30">30 days</option><option value="90" selected>90 days</option><option value="180">180 days</option><option value="365">365 days</option></select><button onclick="loadDash()">Apply</button></div><section id="metrics" class="grid" style="margin-top:18px"></section><section class="panel"><h2>Provider performance</h2><div id="providers"></div></section><section class="panel"><h2>Visibility by query type</h2><div id="types"></div></section><section class="panel"><h2>Monthly trend</h2><div id="trend"></div></section><section class="panel"><h2>Most-cited TechSelectAI pages</h2><div id="pages"></div></section><section class="panel"><h2>Missed opportunities</h2><p class="muted">Valid benchmark answers where TechSelectAI was not cited. Use these to prioritize content and authority work.</p><div id="gaps"></div></section><section class="panel"><h2>Import benchmark run</h2><p class="muted">Use manual or permitted semi-automated testing. Each row must reference a seeded <code>prompt_key</code>. Status may be <code>valid</code>, <code>ambiguous</code>, or <code>failed</code>.</p><div class="filters"><input id="runProvider" placeholder="Provider e.g. ChatGPT"><input id="model" placeholder="Model/version"><select id="mode"><option>manual</option><option>semi_automated</option><option>import</option><option>automated</option></select></div><textarea id="payload">[
  {"prompt_key":"crm-best-general","status":"valid","mentioned":true,"cited":true,"cited_url":"https://techselectai.com/software/example","source_position":2,"other_sources":["g2.com","capterra.com"],"answer_date":"2026-09-11 12:00:00"}
]</textarea><button onclick="importRun()">Import run</button><span id="msg" class="muted"></span></section><section class="panel"><h2>Benchmark prompt set</h2><div id="prompts"></div></section></main><script>
let csrf='';const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function api(url,opt={}){opt.headers={...(opt.headers||{}),'Content-Type':'application/json','X-CSRF-Token':csrf};let r=await fetch(url,opt),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Request failed');if(d.csrf_token)csrf=d.csrf_token;return d}function tbl(rows,cols){if(!rows?.length)return '<p class="muted">No data yet.</p>';return '<table><thead><tr>'+cols.map(c=>'<th>'+esc(c[1])+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+cols.map(c=>'<td>'+esc(r[c[0]]??'')+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
async function loadDash(){let d=await api('/api/ai-visibility/dashboard?provider='+encodeURIComponent(provider.value)+'&days='+days.value);let m=d.metrics;metrics.innerHTML=[['Valid observations',m.valid_observations],['Mention rate',m.mention_rate+'%'],['Citation rate',m.citation_rate+'%'],['Unique cited pages',m.unique_pages]].map(x=>`<div class="card"><div class="muted">${x[0]}</div><div class="n">${esc(x[1])}</div></div>`).join('');providers.innerHTML=tbl(d.by_provider,[['label','Provider'],['n','Valid'],['mention_rate','Mention %'],['citation_rate','Citation %']]);types.innerHTML=tbl(d.by_query_type,[['label','Query type'],['n','Valid'],['mention_rate','Mention %'],['citation_rate','Citation %']]);trend.innerHTML=tbl(d.trend,[['label','Month'],['n','Valid'],['mention_rate','Mention %'],['citation_rate','Citation %']]);pages.innerHTML=tbl(d.top_cited_pages,[['label','URL'],['n','Citations']]);gaps.innerHTML=tbl(d.gaps,[['provider','Provider'],['query_type','Type'],['prompt_text','Prompt'],['answer_date','Date']]);}
async function loadPrompts(){let d=await api('/api/ai-visibility/prompts');prompts.innerHTML=tbl(d.prompts,[['prompt_key','Key'],['query_type','Type'],['category_key','Category'],['prompt_text','Prompt']])}async function importRun(){try{let observations=JSON.parse(payload.value);let d=await api('/api/ai-visibility/import',{method:'POST',body:JSON.stringify({provider:runProvider.value,model_name:model.value,run_mode:mode.value,observations})});msg.textContent=`Imported run ${d.run_id} with ${d.observations} observations.`;await loadDash()}catch(e){msg.textContent=e.message}}loadPrompts();loadDash();
</script></body></html>